const events = $input.all().map(i => i.json);
if (!events.length || !events[0].id) {
  return [{ json: { agenda: ':sunny: No meetings today. Deep work day!' } }];
}
const lines = events
  .sort((a, b) => new Date(a.start?.dateTime || a.start?.date) - new Date(b.start?.dateTime || b.start?.date))
  .map(e => {
    const link = e.hangoutLink || (e.location && e.location.startsWith('http') ? e.location : null);
    if (!e.start?.dateTime) return `- *All day:* ${e.summary}`;
    const t = new Date(e.start.dateTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    return `- *${t}* ${e.summary}${link ? ` (<${link}|join>)` : ''}`;
  });
return [{ json: { agenda: `:calendar: *Today's agenda*\n${lines.join('\n')}` } }];
